// MA0048: Fixture types grouped in one file.
#pragma warning disable MA0048

namespace ModernLibs.FileHelpers.Tests.Compat;

/// <summary>
/// Delimited record with quoted, trimmed, converted, nullable and optional fields; the descriptor is generated
/// by the current generator. <see cref="Compat48Quoted"/> has the same members and a descriptor generated by 4.8.0.
/// </summary>
[DelimitedRecord(",")]
[IgnoreFirst(1)]
public sealed class Compat48QuotedTwin
{
    [FieldOrder(1)] public int Id { get; set; }

    [FieldOrder(2)]
    [FieldQuoted('"', QuoteMode.OptionalForBoth, MultilineMode.AllowForBoth)]
    public string Name { get; set; } = string.Empty;

    [FieldOrder(3)]
    [FieldConverter(ConverterKind.Decimal, ".")]
    public decimal Amount { get; set; }

    [FieldOrder(4)]
    [FieldConverter(ConverterKind.Date, "yyyy-MM-dd")]
    public DateTime Day { get; set; }

    [FieldOrder(5)]
    [FieldTrim(TrimMode.Both)]
    public string Code { get; set; } = string.Empty;

    [FieldOrder(6)] public int? Count { get; set; }

    [FieldOrder(7)]
    [FieldOptional]
    [FieldQuoted]
    public string? Note { get; set; }
}

/// <summary>
/// The members of <see cref="Compat48QuotedTwin"/> without record attributes: its descriptor is the checked-in
/// 4.8.0 output in <c>Generated48</c>.
/// </summary>
public sealed class Compat48Quoted
{
    public int Id { get; set; }

    public string Name { get; set; } = string.Empty;

    public decimal Amount { get; set; }

    public DateTime Day { get; set; }

    public string Code { get; set; } = string.Empty;

    public int? Count { get; set; }

    public string? Note { get; set; }
}

/// <summary>The members of <see cref="Compat48FixedTwin"/>; its descriptor is the checked-in 4.8.0 output.</summary>
public struct Compat48Fixed
{
    public int Id { get; set; }

    public string Name { get; set; }

    public DateTime Day { get; set; }

    public decimal Amount { get; set; }
}

/// <summary>Fixed-length struct record with alignment and a date; see <see cref="Compat48QuotedTwin"/>.</summary>
[FixedLengthRecord]
public struct Compat48FixedTwin
{
    [FieldOrder(1)]
    [FieldFixedLength(6)]
    [FieldAlign(AlignMode.Right, '0')]
    public int Id { get; set; }

    [FieldOrder(2)]
    [FieldFixedLength(10)]
    [FieldTrim(TrimMode.Right)]
    public string Name { get; set; }

    [FieldOrder(3)]
    [FieldFixedLength(8)]
    public DateTime Day { get; set; }

    [FieldOrder(4)]
    [FieldFixedLength(9)]
    [FieldAlign(AlignMode.Right)]
    [FieldConverter(ConverterKind.Decimal, ".")]
    public decimal Amount { get; set; }
}
